using System;
using System.IO;
using System.Linq;
using System.Collections;
using System.Reflection;
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.SceneManagement;
using CatCafePreview.Standalone;
namespace CatCafePreview
{
    public sealed class StandaloneEndingSmoke:MonoBehaviour
    {
        string output;int checks;bool failed;static readonly BindingFlags Hidden=BindingFlags.Instance|BindingFlags.NonPublic;
        public static LocalCafeBackend Create(string path){var r=StandaloneEncounterConversationSmoke.Rules();r.goal_stages=new[]{new GoalStageRule{days=20,target=1}};return new LocalCafeBackend(path,r);}
        static void Good(LocalCafeBackend b,string kind,string choice=null,int slot=1)=>StandaloneDispatchConversationSmoke.Good(b,kind,choice,slot:slot);
        static void Setup(LocalCafeBackend b){Good(b,"new_game","popularity");Good(b,"day_off");}
        public static int BackendChecks(string path,bool restart)
        {
            int n=0;Action<bool,string> check=(ok,label)=>{n++;if(!ok)throw new Exception(label);};var b=Create(path);if(restart){Good(b,"load_game",slot:2);check(b.PopularityEnding.progress.node==2,"Restart node lost");check(b.Replays.Load().entries.Any(e=>e.conversation_id==CafePopularityEnding.Id),"Restart archive lost");}
            bool alreadyViewed=b.Replays.Load().entries.Any(e=>e.conversation_id==CafePopularityEnding.Id);Setup(b);check(b.Simulation.GoalWaiting && b.PopularityEndingPending,"Final clear did not begin ending");var p=b.PopularityEnding.progress;var record=JsonUtility.ToJson(CafePopularityEnding.Record(b.Simulation.State));
            check(StandaloneDispatchConversationSmoke.Raw(b,JsonUtility.ToJson(new PythonShiftCommand{kind="continue_goal",request_id=Guid.NewGuid().ToString("N"),instance_id=b.Simulation.State.instance_id,expected_revision=b.Simulation.State.revision,working_cats=new string[0]})).result!=UnityEngine.Networking.UnityWebRequest.Result.Success,"Unfinished ending allowed continue");
            int length=CafePopularityEnding.Lines(CafePopularityEnding.Record(b.Simulation.State),"猫").Length;
            for(int node=0;node<=length;node++){p.node=node;Good(b,"save_game",slot:3);Good(b,"load_game",slot:3);p=b.PopularityEnding.progress;check(p.node==node && !p.completed && record==JsonUtility.ToJson(CafePopularityEnding.Record(b.Simulation.State)),"Ending save position/result changed");}
            p.node=2;Good(b,"save_game",slot:2);check(b.Replays.Load().entries.Any(e=>e.conversation_id==CafePopularityEnding.Id)==alreadyViewed,"Partial ending changed unlock");p.node=length;CafePopularityEnding.Finish(p);CafePopularityEnding.Finish(p);b.RememberViewedConversations();Good(b,"save_game",slot:4);check(b.Replays.Load().entries.Count(e=>e.conversation_id==CafePopularityEnding.Id)==1,"Ending unlock duplicated");Good(b,"continue_goal");check(!b.Simulation.GoalWaiting && record==JsonUtility.ToJson(CafePopularityEnding.Record(b.Simulation.State)),"Continue changed clear record");
            Good(b,"load_game",slot:4);check(b.PopularityEnding.progress.completed && !b.PopularityEndingPending,"Completed save reran ending");
            var old=JsonUtility.FromJson<CafeSaveEnvelope>(File.ReadAllText(Path.Combine(path,"slot-4.json")));old.popularity_ending=null;old.slot=5;File.WriteAllText(Path.Combine(path,"slot-5.json"),JsonUtility.ToJson(old));Good(b,"load_game",slot:5);check(b.PopularityEndingPending,"Old pending save did not offer ending");
            old.state.goal.Last().continued=true;old.slot=6;File.WriteAllText(Path.Combine(path,"slot-6.json"),JsonUtility.ToJson(old));Good(b,"load_game",slot:6);check(b.PopularityEnding==null,"Old continued save reblocked");
            var bad=JsonUtility.FromJson<CafeSaveEnvelope>(File.ReadAllText(Path.Combine(path,"slot-4.json")));bad.popularity_ending.progress.node=999;bool rejected=false;try{CafePopularityEnding.Validate(bad.popularity_ending,bad.state);}catch(ArgumentException){rejected=true;}check(rejected,"Invalid node accepted");
            Good(b,"new_game","free");check(b.PopularityEnding==null && b.Replays.Load().entries.Count(e=>e.conversation_id==CafePopularityEnding.Id)==1,"New game lost archive or retained pending");var staged=StandaloneEncounterConversationSmoke.Rules();staged.goal_stages[0].target=1;var middle=new LocalCafeBackend(Path.Combine(path,"middle-"+Guid.NewGuid().ToString("N")),staged);Setup(middle);check(middle.Simulation.GoalWaiting && middle.PopularityEnding==null,"Intermediate stage opened ending");Good(middle,"continue_goal");
            var timed=StandaloneEncounterConversationSmoke.Rules();timed.goal_stages=new[]{new GoalStageRule{days=1,target=timed.popularity.cap}};var expired=new LocalCafeBackend(Path.Combine(path,"expired-"+Guid.NewGuid().ToString("N")),timed);Setup(expired);check(expired.Simulation.State.goal.Last().status=="expired" && expired.PopularityEnding==null,"Expired goal opened success ending");Good(expired,"continue_goal");
            foreach(var mode in new[]{"bond","patron"}){Good(b,"new_game",mode);check(b.PopularityEnding==null,"Other goal opened popularity ending");}return n;
        }
        void Check(bool ok,string label){checks++;if(!ok)throw new Exception(label);}
        void Fail(Exception e){if(failed)return;failed=true;File.WriteAllText(Path.Combine(output,"failure.txt"),e.ToString());Debug.LogException(e);Application.Quit(1);}
        void Log(string m,string stack,LogType type){if(type==LogType.Error || type==LogType.Exception || type==LogType.Assert)Fail(new Exception(m+"\n"+stack));}
        void OnDestroy(){Application.logMessageReceived-=Log;}
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Install(){var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,"--catcafe-ending-check");if(i<0)return;var qa=new GameObject("Ending verification").AddComponent<StandaloneEndingSmoke>();DontDestroyOnLoad(qa);qa.output=Path.GetFullPath(args[i+1]);Directory.CreateDirectory(qa.output);Application.runInBackground=true;Application.logMessageReceived+=qa.Log;try{qa.checks=BackendChecks(Path.Combine(qa.output,"cases"),args.Contains("--ending-restart"));qa.StartCoroutine(qa.Guard());}catch(Exception e){qa.Fail(e);}}
        IEnumerator Guard(){var run=Run();while(true){bool more;try{more=run.MoveNext();}catch(Exception e){Fail(e);yield break;}if(!more)yield break;yield return run.Current;}}
        IEnumerator Run()
        {
            var b=Create(Path.Combine(output,"ui-"+Guid.NewGuid().ToString("N")));Setup(b);CafeBackends.UseLocal(b);SceneManager.LoadScene("CatCafePythonState");yield return new WaitForSecondsRealtime(2);var preview=FindObjectOfType<ContentPreview>();var ui=preview.GetComponent<PopularityEndingPanel>();Check(ui!=null && ui.Showing,"Ending not visible");var p=b.PopularityEnding.progress;var priority=b.View();priority.required_action="dispatch_return";ui.Apply(priority,preview.GetComponent<PythonGoalPanel>());Check(!ui.Showing && p.node==0,"Ending ignored higher priority event");ui.Apply(b.View(),preview.GetComponent<PythonGoalPanel>());ui.Open();yield return null;var client=preview.GetComponent<PythonStateClient>();var actual=client.CurrentState;var otherGoal=b.View();otherGoal.goal_result.kind="continue_bond_goal";otherGoal.goal_result.can_continue=true;typeof(PythonStateClient).GetField("current",Hidden).SetValue(client,otherGoal);Check(client.CanContinueGoal,"Popularity ending blocked another goal response");typeof(PythonStateClient).GetField("current",Hidden).SetValue(client,actual);string state=JsonUtility.ToJson(b.Simulation.State);typeof(AcquisitionConversationPanel).GetField("revealed",Hidden).SetValue(ui,0f);ui.Next();ui.Next();Check(p.node==0,"Double click skipped line");yield return null;ui.Next();Check(p.node==1,"Next did not advance");ui.Close();yield return null;Check(!ui.Showing && preview.GetComponent<PythonGoalPanel>().resume.interactable,"Closed ending not resumable");preview.GetComponent<PythonGoalPanel>().Continue();yield return null;Check(ui.Showing && p.node==1,"Resume reset line");ui.Panel.GetComponentsInChildren<Button>(true).Single(x=>x.name=="バックログ").onClick.Invoke();yield return null;Check(ui.HistoryScroll.content.rect.height>=ui.HistoryScroll.content.GetComponent<Text>().preferredHeight-1,"Backlog clipped");yield return null;ui.Panel.GetComponentsInChildren<Button>(true).Single(x=>x.name=="バックログ").onClick.Invoke();yield return null;
            p.node=CafePopularityEnding.Lines(CafePopularityEnding.Record(b.Simulation.State),"猫").Length;ui.Refresh();yield return null;ui.Next();yield return null;Check(ui.Outro.activeSelf && !ui.Showing && p.completed,"Outro not shown");Check(state==JsonUtility.ToJson(b.Simulation.State),"Ending changed gameplay");Good(b,"save_game",slot:7);Good(b,"continue_goal");yield return new WaitForSecondsRealtime(2.2f);Check(!ui.Outro.activeSelf && !b.Simulation.GoalWaiting,"Continue did not close outro");Good(b,"load_game",slot:7);yield return new WaitForSecondsRealtime(2.2f);Check(ui.Outro.activeSelf && b.PopularityEnding.progress.completed,"Completed result save not restored");
            SceneManager.LoadScene("CatCafeTitle");yield return new WaitForSecondsRealtime(2);var extra=FindObjectOfType<PythonTitleScreen>().GetComponent<TitleExtraPanel>();extra.Open();extra.Panel.transform.Find("エンディング").GetComponent<Button>().onClick.Invoke();yield return null;extra.OpenReplay(CafePopularityEnding.Id+"/"+CafePopularityEnding.Branch);yield return null;Check(extra.Replay.Showing,"Ending replay locked");string before=JsonUtility.ToJson(b.Simulation.State);extra.Replay.Next();yield return null;extra.Replay.Close();Check(before==JsonUtility.ToJson(b.Simulation.State),"Replay changed gameplay");File.WriteAllText(Path.Combine(output,"result.txt"),"PASS: "+checks+" ending checks; zero Unity errors.");
        }
    }
}
